function saveLineIndexes(text) {
        var result = [0],
            i = 0,
            il = text.length,
            ch, ch2;

        while (i < il) {
            ch = text.charAt(i);

            if (ch == '\n' || ch == '\r') {
                if (ch == '\r' && i < il - 1 && text.charAt(i + 1) == '\n') {
                    // windows line ending: CRLF. Skip next character
                    i++;
                }

                result.push(i + 1);
            }

            i++;
        }

        return result;
    }

